import subprocess
import shlex

def executeCommand():
    '''
    Read a command from a user input, validate it, and execute it
    '''
    # Define allowed commands for security
    allowed_commands = {'ls', 'pwd', 'echo', 'date', 'whoami', 'cat', 'head', 'tail'}

    try:
        # Get user input
        user_input = input("Enter a command: ").strip()

        # Parse the command to separate command and arguments
        parts = shlex.split(user_input)

        # Check if there's a command
        if not parts:
            print("No command provided.")
            return

        # Extract the base command (first part)
        command = parts[0]

        # Validate the command
        if command not in allowed_commands:
            print(f"Command '{command}' is not allowed.")
            return

        # Execute the command safely using subprocess
        try:
            result = subprocess.run(parts, capture_output=True, text=True, timeout=10)
            if result.stdout:
                print(result.stdout)
            if result.stderr:
                print(result.stderr, file=sys.stderr)
        except subprocess.TimeoutExpired:
            print("Command execution timed out.")
        except Exception as e:
            print(f"Error executing command: {e}")

    except EOFError:
        print("No input provided.")
    except Exception as e:
        print(f"Error reading input: {e}")
